## Why This Is Asked
This tests basic algorithmic analysis and trade-offs between brute force and divide-and-conquer techniques.

## Key Concepts
- Time complexity and space usage
- Inversions problem and two standard approaches
- Trade-offs with input size and data order

## Code Example
```javascript
function countInversionsNaive(a){
  let c=0;
  for(let i=0;i<a.length;i++){
    for(let j=i+1;j<a.length;j++){
      if(a[i]>a[j]) c++;
    }
  }
  return c;
}
function countInversionsMergeSort(a){
  function sortCount(arr){
    if(arr.length<=1) return {array: arr, inv:0};
    const mid = Math.floor(arr.length/2);
    const left = sortCount(arr.slice(0,mid));
    const right = sortCount(arr.slice(mid));
    let i=0,j=0, merged=[], inv= left.inv + right.inv;
    while(i<left.array.length && j<right.array.length){
      if(left.array[i] <= right.array[j]) merged.push(left.array[i++]);
      else { merged.push(right.array[j++]); inv += left.array.length - i; }
    }
    return {array: merged.concat(left.array.slice(i)).concat(right.array.slice(j)), inv: inv};
  }
  return sortCount(a).inv;
}
```

